import XCTest
@testable import VaultKit

/// Differential hash coverage generated by an independent implementation
/// (`tools/derive/`, pycryptodome + hashlib) over 306 input lengths, chosen to
/// straddle every block boundary (64-byte SHA-256/RIPEMD-160 blocks, 128-byte
/// SHA-512 blocks, 136-byte Keccak rate) plus larger sizes.
///
/// This is the test that caught the Keccak `0x81` padding-collapse bug at
/// lengths 135 and 271.
final class HashDifferentialTests: XCTestCase {

    func testAllHashVectors() throws {
        let text = try FixtureLoader.text("hash_vectors", extension: "txt")
        var counts: [String: Int] = [:]

        for line in text.split(separator: "\n") {
            let parts = line.split(separator: " ")
            guard parts.count == 3, let length = Int(parts[1]) else {
                XCTFail("malformed fixture line: \(line)")
                continue
            }
            let algorithm = String(parts[0])
            let expected = String(parts[2])
            let input = [UInt8](repeating: UInt8(ascii: "a"), count: length)

            let actual: String
            switch algorithm {
            case "sha256": actual = Hex.encode(SHA256.hash(input))
            case "sha512": actual = Hex.encode(SHA512.hash(input))
            case "ripemd160": actual = Hex.encode(RIPEMD160.hash(input))
            case "keccak256": actual = Hex.encode(Keccak256.hash(input))
            default:
                XCTFail("unknown algorithm in fixture: \(algorithm)")
                continue
            }

            XCTAssertEqual(actual, expected, "\(algorithm) length \(length)")
            counts[algorithm, default: 0] += 1
        }

        // Guard against a truncated/empty fixture silently passing.
        XCTAssertEqual(counts["sha256"], 306)
        XCTAssertEqual(counts["sha512"], 306)
        XCTAssertEqual(counts["ripemd160"], 306)
        XCTAssertEqual(counts["keccak256"], 306)
    }

    /// HMAC boundary coverage: keys on both sides of the 128-byte block size.
    func testHMACBoundaryLengths() throws {
        let text = try FixtureLoader.text("hmac_sha512_vectors", extension: "txt")
        var count = 0
        for line in text.split(separator: "\n") {
            let parts = line.split(separator: " ")
            guard parts.count == 4, let keyLen = Int(parts[0]), let msgLen = Int(parts[1]) else {
                XCTFail("malformed fixture line: \(line)")
                continue
            }
            let key = [UInt8](repeating: 0x0b, count: keyLen)
            let message = [UInt8](repeating: 0xcd, count: msgLen)
            XCTAssertEqual(
                Hex.encode(HMACSHA512.authenticate(key: key, message: message)),
                String(parts[3]),
                "key \(keyLen) message \(msgLen)"
            )
            count += 1
        }
        XCTAssertGreaterThan(count, 0)
    }
}
